package za.co.loopmanager;
import android.app.*;import android.app.job.*;import android.content.*;import android.content.pm.*;import android.net.*;import android.os.*;import org.json.JSONObject;import java.io.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import za.co.bacy.ui.ApkUpdates;
/** Immediate Wi-Fi checks, verified automatic downloads and explicit install approval. */
final class ManagedUpdates {
 private static final AtomicInteger VISIBLE=new AtomicInteger();private static final AtomicBoolean RUNNING=new AtomicBoolean();private static final ExecutorService WORKER=Executors.newSingleThreadExecutor();private static long lastCheck;
 static void visible(boolean value){if(value)VISIBLE.incrementAndGet();else VISIBLE.updateAndGet(n->Math.max(0,n-1));}
 static boolean busy(){return VISIBLE.get()>0||CheckoutAccess.active();}
 static boolean wifi(Context c){ConnectivityManager m=c.getSystemService(ConnectivityManager.class);NetworkCapabilities n=m.getNetworkCapabilities(m.getActiveNetwork());return n!=null&&n.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)&&n.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)&&!m.isActiveNetworkMetered();}
 static void schedule(Context c){if(!PolicyController.owns(c))return;c.getSystemService(JobScheduler.class).schedule(new JobInfo.Builder(402,new ComponentName(c,UpdateJobService.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_UNMETERED).setRequiresBatteryNotLow(true).setPeriodic(6*60*60*1000L).setPersisted(true).build());}
 static void checkSoon(Context c){trigger(c,false);}
 static void trigger(Context input,boolean manual){Context c=input.getApplicationContext();if(!PolicyController.owns(c)||(!manual&&!wifi(c)))return;synchronized(ManagedUpdates.class){long now=SystemClock.elapsedRealtime();if(!manual&&lastCheck>0&&now-lastCheck<60000)return;if(!RUNNING.compareAndSet(false,true))return;lastCheck=now;}WORKER.execute(()->{try{execute(c,manual);}catch(Exception e){UpdateGate.clear(c);status(c,"failed","Update could not complete. Your current app and account are retained. Retry from App updates.",0);}finally{RUNNING.set(false);}});}
 static void request(Context c){trigger(c,true);}
 static boolean run(Context c,boolean manual){if(!RUNNING.compareAndSet(false,true))return false;try{if(manual||wifi(c))execute(c,manual);return false;}catch(Exception e){UpdateGate.clear(c);status(c,"failed","Update could not complete. Your account is retained; retry from App updates.",0);return true;}finally{RUNNING.set(false);}}
 static String installedAt(Context c){try{long at=c.getPackageManager().getPackageInfo(c.getPackageName(),0).lastUpdateTime;return at>0?java.text.DateFormat.getDateTimeInstance(java.text.DateFormat.MEDIUM,java.text.DateFormat.SHORT).format(new java.util.Date(at)):"Not reported by Android";}catch(Exception e){return "Not reported by Android";}}
 static String cachedSize(Context c){File apk=new File(c.getFilesDir(),"updates/client.apk");return apk.isFile()?String.format(java.util.Locale.ROOT,"%.1f MB",apk.length()/1000000d):"No saved download";}
 static String describe(Context c){var p=c.getSharedPreferences("loop.updates",0);return "App version "+BuildConfig.VERSION_NAME+"\nInstalled: "+installedAt(c)+"\nCached download: "+cachedSize(c)+"\nChecks on app opening and Wi-Fi connection. Downloads are automatic; tap Install when ready.\n"+p.getString("status","No update check recorded yet.");}
 static void status(Context c,String text){status(c,"failed",text,0);}
 static void status(Context c,String stage,String text,int progress){var p=c.getSharedPreferences("loop.updates",0);p.edit().putString("stage",stage).putString("status",text).putInt("progress",progress).apply();c.sendBroadcast(new Intent(LiveConnectionService.UPDATED).putExtra("update_changed",true).setPackage(c.getPackageName()),c.getPackageName()+".permission.INTERNAL");if(stage.equals("ready")){NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("app-updates","App updates",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(c,405,new Intent(c,MainActivity.class).putExtra("open_updates",true),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);nm.notify(405,new Notification.Builder(c,"app-updates").setSmallIcon(android.R.drawable.stat_sys_download_done).setContentTitle("Loop Secure update ready").setContentText("Tap to review and install the verified update.").setContentIntent(open).setAutoCancel(true).build());}}
 static boolean trustedUrl(String value){return ApkUpdates.trustedUrl(value,"client");}
 static void validate(JSONObject m,String id,long now,long current)throws Exception{ApkUpdates.validate(m,id,"client_update","za.co.loopmanager","client",now,current);}
 static JSONObject verifyManifest(Store s,JSONObject envelope,long now,long current)throws Exception {JSONObject m=ApkUpdates.decode(envelope,s.get("public_key"));validate(m,s.get("device_id"),now,current);return m;}
 private static void execute(Context c,boolean install)throws Exception {
  Store store=new Store(c);if(store.get("device_token").isEmpty())return;Entitlement account=Sync.run(c);if(account==null||account.data.optBoolean("released")){UpdateGate.clear(c);return;}
  var pi=c.getPackageManager().getPackageInstaller();var p=c.getSharedPreferences("loop.updates",0);int pending=p.getInt("session",-1);if(pending>=0&&pi.getSessionInfo(pending)!=null){status(c,"installing","Android is completing the update installation.",100);return;}p.edit().remove("session").apply();
  status(c,"checking","Checking the server for an update…",0);long current=c.getPackageManager().getPackageInfo(c.getPackageName(),0).getLongVersionCode();JSONObject m=verifyManifest(store,new Api(store).post("/api/device/app-update",new JSONObject().put("version_code",current),true),account.serverNow(c),current);
  if(!m.optBoolean("available")){UpdateGate.clear(c);status(c,"current","Your app is up to date.",100);return;}
  File apk=new File(c.getFilesDir(),"updates/client.apk");boolean valid=false;if(apk.exists())try{ApkUpdates.verifyFile(c,apk,m);valid=true;}catch(Exception ignored){}
  if(m.optBoolean("required",true))UpdateGate.begin(c,m.getLong("version_code"));p.edit().putString("version_name",m.getString("version_name")).apply();
  if(!valid){status(c,"downloading","Downloading update "+m.getString("version_name")+"…",0);ApkUpdates.download(c,m,apk,n->status(c,"downloading","Downloading update… "+n+"%",n));}
  if(!install||CheckoutAccess.active()){status(c,"ready","Update downloaded and verified. Tap Install update when ready.",100);return;}
  validate(m,store.get("device_id"),account.serverNow(c),current);ApkUpdates.verifyFile(c,apk,m);if(!PolicyController.owns(c))throw new SecurityException("Device management changed");
  PackageInstaller.SessionParams params=new PackageInstaller.SessionParams(PackageInstaller.SessionParams.MODE_FULL_INSTALL);params.setAppPackageName(c.getPackageName());params.setSize(apk.length());if(Build.VERSION.SDK_INT>=31)params.setRequireUserAction(PackageInstaller.SessionParams.USER_ACTION_NOT_REQUIRED);int id=pi.createSession(params);p.edit().putInt("session",id).apply();boolean committed=false;
  try(PackageInstaller.Session session=pi.openSession(id)){try(InputStream in=new FileInputStream(apk);OutputStream out=session.openWrite("base.apk",0,apk.length())){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1)out.write(b,0,n);session.fsync(out);}Intent callback=new Intent(c,UpdateReceiver.class).setAction("za.co.loopmanager.UPDATE_RESULT");int flags=PendingIntent.FLAG_UPDATE_CURRENT;if(Build.VERSION.SDK_INT>=31)flags|=PendingIntent.FLAG_MUTABLE;status(c,"installing","Installing the verified update. Account data is retained.",100);session.commit(PendingIntent.getBroadcast(c,id,callback,flags).getIntentSender());committed=true;}finally{if(!committed){pi.abandonSession(id);p.edit().remove("session").apply();}}
 }
}
